 measure();const blockHeight=lines.length*(ascent+descent)+(lines.length-1)*gap,top=(height-blockHeight)/2;
 const positions=lines.map((line,i)=>{const m=metrics[i],left=m.actualBoundingBoxLeft||0,right=m.actualBoundingBoxRight??m.width,x=(width-left-right)/2+left,y=top+ascent+i*(ascent+descent+gap);context.fillText(line,x,y);return {x,y,left:x-left,right:x+right,top:y-ascent,bottom:y+descent}});
