export const textColumnMinimum=text=>Math.max(30,Math.min(120,Math.max(...String(text).split('\n').slice(0,5).map(line=>Array.from(line).length))*12));
export function textSampling(bounds,columns,width=720,height=405,lineCount=1){const left=Math.max(0,Math.floor(Math.min(...bounds.map(b=>b.left))-8)),right=Math.min(width,Math.ceil(Math.max(...bounds.map(b=>b.right))+8)),top=Math.max(0,Math.floor(Math.min(...bounds.map(b=>b.top))-8)),bottom=Math.min(height,Math.ceil(Math.max(...bounds.map(b=>b.bottom))+8)),w=Math.max(1,right-left),h=Math.max(1,bottom-top);return {x:left,y:top,width:w,height:h,rows:Math.min(100,Math.max(lineCount*12+4,Math.round(columns*h/w/2)))}}
export function asciiTool({change,status}){const $=id=>document.getElementById(id);let image=null,output='',loadEpoch=0;const state=()=>({text:$('ascii-text').value.slice(0,200),columns:Number($('ascii-width').value),ramp:Number($('ascii-characters').value),dither:$('ascii-dither').checked,invert:$('ascii-invert').checked});
  function fit(){const actual=$('ascii-preview-scale').value==='actual',box=$('ascii-preview'),columns=Number($('ascii-width').value),style=getComputedStyle(box),padding=(parseFloat(style.paddingLeft)||0)+(parseFloat(style.paddingRight)||0),vertical=(parseFloat(style.paddingTop)||0)+(parseFloat(style.paddingBottom)||0),height=(parseFloat(style.maxHeight)||620)-vertical,rows=Math.max(1,output.split('\n').length),lineBudget=Math.max(5,Math.floor(height/rows)),size=actual?10:Math.min(10,(box.clientWidth-padding)/Math.max(1,columns)/.61,lineBudget/1.4);box.style.fontSize=Math.max(3,size)+'px';box.style.lineHeight=Math.ceil(Math.max(3,size)*1.4)+'px';const scroll=actual||columns*.61*Math.max(3,size)>box.clientWidth-padding;$('ascii-scroll-controls').hidden=!scroll;$('ascii-scroll-hint').hidden=!scroll}
  $('ascii-preview-scale').onchange=fit;$('ascii-scroll-left').onclick=()=>$('ascii-preview').scrollBy({left:-160,behavior:'auto'});$('ascii-scroll-right').onclick=()=>$('ascii-preview').scrollBy({left:160,behavior:'auto'});new ResizeObserver(fit).observe($('ascii-preview'));
  function draw(){const s=state(),minimum=image?30:textColumnMinimum(s.text);$('ascii-width').min=minimum;const width=clamp(s.columns,minimum,160);$('ascii-width').value=width;const source=document.createElement('canvas');source.width=720;source.height=405;const c=source.getContext('2d',{willReadFrequently:true});c.fillStyle='white';c.fillRect(0,0,720,405);let sampling;if(image){const ratio=Math.min(720/image.width,405/image.height),w=image.width*ratio,h=image.height*ratio;c.drawImage(image,(720-w)/2,(405-h)/2,w,h)}else{sampling=textSampling(drawAsciiText(c,s.text,720,405),width,720,405,Math.min(5,s.text.split('\n').length))}const height=sampling?.rows||Math.round(width*405/720/2),small=document.createElement('canvas');small.width=width;small.height=height;const ctx=small.getContext('2d',{willReadFrequently:true});if(sampling)ctx.drawImage(source,sampling.x,sampling.y,sampling.width,sampling.height,0,0,width,height);else ctx.drawImage(source,0,0,width,height);output=ascii(ctx.getImageData(0,0,width,height).data,width,height,{characters:CHAR_RAMPS[s.ramp]||CHAR_RAMPS[0],dither:s.dither,invert:s.invert});$('ascii-preview').textContent=output;$('ascii-preview').scrollTop=0;$('ascii-dimensions').textContent=`${width} columns × ${height} rows${image?' · local image':' · text'}`;$('ascii-width-value').value=width;fit();change()}
  for(const id of ['ascii-text','ascii-width','ascii-characters','ascii-dither','ascii-invert'])$(id).oninput=draw;
  $('ascii-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;const epoch=++loadEpoch;try{if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>12*1024*1024)throw Error('Choose a PNG, JPEG or WebP smaller than 12 MB.');const [w,h]=dimensions(await file.arrayBuffer());if(w<1||h<1||w*h>20000000)throw Error('Choose an image under 20 megapixels.');const bitmap=await createImageBitmap(file,{resizeWidth:Math.min(w,1000),resizeQuality:'high'});if(epoch!==loadEpoch){bitmap.close();return}image?.close();image=bitmap;$('ascii-use-text').hidden=false;draw();status('Image loaded locally. It has not been uploaded.')}catch(err){status(err.message,true);e.target.value=''}};
  $('ascii-use-text').onclick=()=>{loadEpoch++;image?.close();image=null;$('ascii-file').value='';$('ascii-use-text').hidden=true;draw()};
  draw();return {get:state,set:v=>{if(!v)return;$('ascii-text').value=String(v.text||'').slice(0,200);$('ascii-width').value=clamp(Number(v.columns)||100,30,160);$('ascii-characters').value=clamp(Number(v.ramp)||0,0,2);$('ascii-dither').checked=v.dither===true;$('ascii-invert').checked=v.invert!==false;draw()},text:()=>output,svg:()=>asciiSVG(output)};
}
